-- Local data of the console shell (profiles, library, achievements, settings).
-- Engine: SQLite 3 (bun:sqlite on the web server side, rusqlite 0.42 on native, SQLite-in-OPFS on wasm).
-- Conventions: ids are TEXT (UUIDv7 generated by the app, sortable by time); times are INTEGER unix
-- milliseconds in UTC; money is integer minor units plus an ISO 4217 code; booleans are 0/1 with CHECK.
-- Access rules: data-layer checks. Every query on a profile-owned table is built through
-- store::scoped(profile_id); there is no row level security in SQLite. Tables without profile_id are shared
-- device data (settings scope 'device', games catalogue, achievements definitions).
-- The games catalogue is read-only and attached at run time:
--   ATTACH DATABASE 'packages/assets/data/games.sqlite' AS idx;   (table idx.games, FTS idx.games_fts)
-- game_ref below is the pair (store, ext_id) of idx.games, never a copy of third-party art.

PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA user_version = 1;

-- Shipped avatars are original art identified by a slug (no third-party characters).
CREATE TABLE avatar (
  id          TEXT PRIMARY KEY,
  slug        TEXT NOT NULL UNIQUE,
  asset_path  TEXT NOT NULL,
  created_at  INTEGER NOT NULL
) STRICT;

CREATE TABLE profile (
  id               TEXT PRIMARY KEY,
  name             TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 32),
  avatar_id        TEXT REFERENCES avatar(id) ON DELETE SET NULL,
  pin_hash         TEXT,                          -- PHC string, NULL = no lock
  is_guest         INTEGER NOT NULL DEFAULT 0 CHECK (is_guest IN (0,1)),
  locale           TEXT NOT NULL DEFAULT 'en' CHECK (locale IN ('fr','en','zh-CN','ja','es')),
  last_profile_at  INTEGER,
  created_at       INTEGER NOT NULL,
  updated_at       INTEGER NOT NULL
) STRICT;
CREATE INDEX profile_last ON profile(last_profile_at DESC);

CREATE TABLE controller (
  slot        INTEGER PRIMARY KEY CHECK (slot BETWEEN 1 AND 8),
  profile_id  TEXT REFERENCES profile(id) ON DELETE SET NULL,
  kind        TEXT NOT NULL CHECK (kind IN ('gamepad','keyboard','touch','remote','other')),
  device_key  TEXT,                               -- stable id from gilrs / winit / Android InputDevice
  battery_pct INTEGER CHECK (battery_pct BETWEEN 0 AND 100),
  updated_at  INTEGER NOT NULL
) STRICT;
CREATE INDEX controller_profile ON controller(profile_id);

-- One row per game the device knows. Local installs and user-added entries; catalogue rows come from idx.games.
CREATE TABLE game (
  id            TEXT PRIMARY KEY,
  store         TEXT NOT NULL,                    -- 'steam','epic','gog','itch','local','web'
  ext_id        TEXT NOT NULL,
  title         TEXT NOT NULL,
  cover_path    TEXT,                             -- user-owned or original art only
  hero_path     TEXT,
  platform      TEXT NOT NULL DEFAULT '',
  size_bytes    INTEGER CHECK (size_bytes >= 0),
  launch_uri    TEXT,                             -- steam://rungameid/.., file path, or URL
  created_at    INTEGER NOT NULL,
  UNIQUE (store, ext_id)
) STRICT;
CREATE INDEX game_title ON game(title COLLATE NOCASE);

CREATE TABLE library (
  profile_id       TEXT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
  game_id          TEXT NOT NULL REFERENCES game(id) ON DELETE CASCADE,
  added_at         INTEGER NOT NULL,
  last_played_at   INTEGER,
  playtime_s       INTEGER NOT NULL DEFAULT 0 CHECK (playtime_s >= 0),
  pinned           INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0,1)),
  hidden           INTEGER NOT NULL DEFAULT 0 CHECK (hidden IN (0,1)),
  PRIMARY KEY (profile_id, game_id)
) STRICT, WITHOUT ROWID;
CREATE INDEX library_recent ON library(profile_id, last_played_at DESC);
CREATE INDEX library_game ON library(game_id);

CREATE TABLE play_session (
  id          TEXT PRIMARY KEY,
  profile_id  TEXT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
  game_id     TEXT NOT NULL REFERENCES game(id) ON DELETE CASCADE,
  started_at  INTEGER NOT NULL,
  ended_at    INTEGER,
  CHECK (ended_at IS NULL OR ended_at >= started_at)
) STRICT;
CREATE INDEX play_session_profile ON play_session(profile_id, started_at DESC);
CREATE INDEX play_session_game ON play_session(game_id);

-- Achievements: original names and original medal art. Tiers are our own (bronze/silver/gold/crown).
CREATE TABLE achievement (
  id           TEXT PRIMARY KEY,
  game_id      TEXT NOT NULL REFERENCES game(id) ON DELETE CASCADE,
  tier         TEXT NOT NULL CHECK (tier IN ('bronze','silver','gold','crown')),
  title_i18n   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(title_i18n)),   -- {"en":"..","fr":".."}
  desc_i18n    TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(desc_i18n)),
  hidden       INTEGER NOT NULL DEFAULT 0 CHECK (hidden IN (0,1)),
  points       INTEGER NOT NULL DEFAULT 0 CHECK (points >= 0)
) STRICT;
CREATE INDEX achievement_game ON achievement(game_id, tier);

CREATE TABLE achievement_progress (
  profile_id      TEXT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
  achievement_id  TEXT NOT NULL REFERENCES achievement(id) ON DELETE CASCADE,
  progress_pct    INTEGER NOT NULL DEFAULT 0 CHECK (progress_pct BETWEEN 0 AND 100),
  earned_at       INTEGER,
  PRIMARY KEY (profile_id, achievement_id),
  CHECK ((earned_at IS NOT NULL) = (progress_pct = 100))
) STRICT, WITHOUT ROWID;
CREATE INDEX achievement_progress_earned ON achievement_progress(profile_id, earned_at DESC);

CREATE TABLE collection (
  id          TEXT PRIMARY KEY,
  title_i18n  TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(title_i18n)),
  kind        TEXT NOT NULL DEFAULT 'editor' CHECK (kind IN ('editor','deal','discover','user')),
  profile_id  TEXT REFERENCES profile(id) ON DELETE CASCADE,    -- NULL = shipped, set = user collection
  sort_order  INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE INDEX collection_profile ON collection(profile_id, sort_order);

CREATE TABLE collection_item (
  collection_id  TEXT NOT NULL REFERENCES collection(id) ON DELETE CASCADE,
  game_id        TEXT NOT NULL REFERENCES game(id) ON DELETE CASCADE,
  position       INTEGER NOT NULL,
  PRIMARY KEY (collection_id, game_id)
) STRICT, WITHOUT ROWID;
CREATE INDEX collection_item_game ON collection_item(game_id);

-- Mock store catalogue for S06 to S08 (no payment, no network): price is display data only.
CREATE TABLE product (
  id          TEXT PRIMARY KEY,
  game_id     TEXT NOT NULL REFERENCES game(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL CHECK (kind IN ('game','subscription','addon')),
  price_minor INTEGER NOT NULL DEFAULT 0 CHECK (price_minor >= 0),
  currency    TEXT NOT NULL DEFAULT 'EUR' CHECK (length(currency) = 3),
  sale_minor  INTEGER CHECK (sale_minor IS NULL OR sale_minor < price_minor),
  release_at  INTEGER
) STRICT;
CREATE INDEX product_game ON product(game_id);

CREATE TABLE news_item (
  id            TEXT PRIMARY KEY,
  game_id       TEXT REFERENCES game(id) ON DELETE SET NULL,
  title_i18n    TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(title_i18n)),
  body_i18n     TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(body_i18n)),
  published_at  INTEGER NOT NULL
) STRICT;
CREATE INDEX news_recent ON news_item(published_at DESC);
CREATE INDEX news_game ON news_item(game_id);

-- Launchable non-game apps (media, emulators, web apps). Icons come from assets/library/icons/vendors.
CREATE TABLE shell_app (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  kind        TEXT NOT NULL CHECK (kind IN ('video','music','emulator','web','tool')),
  icon_path   TEXT,
  launch_uri  TEXT NOT NULL,
  sort_order  INTEGER NOT NULL DEFAULT 0
) STRICT;

CREATE TABLE setting (
  scope       TEXT NOT NULL CHECK (scope IN ('device','profile')),
  profile_id  TEXT NOT NULL DEFAULT '' ,          -- '' for device scope
  key         TEXT NOT NULL,
  value       TEXT NOT NULL CHECK (json_valid(value)),
  updated_at  INTEGER NOT NULL,
  PRIMARY KEY (scope, profile_id, key),
  CHECK ((scope = 'device') = (profile_id = ''))
) STRICT, WITHOUT ROWID;
-- Keys: layout ('ps'|'switch'|'tv'), theme ('aphrody'|'dawn'|'ember'|'frost'|'mono'|'night'|'workshop'),
-- scheme ('light'|'dark'|'auto'), hdr, text_scale, reduce_motion, high_contrast, safe_area_pct, fps_cap,
-- ui_volume, haptics.

CREATE TABLE input_binding (
  profile_id  TEXT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
  device_kind TEXT NOT NULL CHECK (device_kind IN ('gamepad','keyboard','touch','remote')),
  action      TEXT NOT NULL CHECK (action IN ('up','down','left','right','select','back','prev_tab','next_tab','options','home')),
  code        TEXT NOT NULL,
  PRIMARY KEY (profile_id, device_kind, action)
) STRICT, WITHOUT ROWID;

CREATE TABLE search_history (
  id          INTEGER PRIMARY KEY,
  profile_id  TEXT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
  query       TEXT NOT NULL,
  at          INTEGER NOT NULL
) STRICT;
CREATE INDEX search_history_profile ON search_history(profile_id, at DESC);

-- Offline sync journal for the companion (apps/aphrody-app): last-writer-wins by (updated_at, device_id).
CREATE TABLE sync_op (
  id          TEXT PRIMARY KEY,
  profile_id  TEXT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
  device_id   TEXT NOT NULL,
  tbl         TEXT NOT NULL,
  row_key     TEXT NOT NULL,
  op          TEXT NOT NULL CHECK (op IN ('put','del')),
  payload     TEXT CHECK (payload IS NULL OR json_valid(payload)),
  at          INTEGER NOT NULL,
  applied     INTEGER NOT NULL DEFAULT 0 CHECK (applied IN (0,1))
) STRICT;
CREATE INDEX sync_op_pending ON sync_op(profile_id, applied, at);

-- GDPR-style deletion of a profile: DELETE FROM profile WHERE id = ?; every owned table cascades.
